/* From Uiverse.io by suda-code - Tags: green, button, duolingo */
.__UIV_SCOPE__ button {
  align-items: center;
  color: #ffffff;
  font-size: 18px;
  background: #58cc02;
  border: none !important;
  padding: 15px 16px;
  box-shadow: 0 4px 0 #58a700;
  border-radius: 12px;
  cursor: pointer;
}

.__UIV_SCOPE__ button:active {
  box-shadow: none;
  transform: translate(0, 4px);
}
